-- Summative B (Version B) — safe forward update of repaired questions.
-- Generated by scripts/exam-import/build_summative_b_content_fixes.py; do not edit.
--
-- The four paper migrations import with ON CONFLICT DO NOTHING, so they cannot
-- repair a question that is already live. This file rewrites the repaired rows
-- in place, preserving every UUID, and fails closed rather than rewriting a
-- paper that has been attempted or an option set it does not recognise.
--
--   MYP2-SUMMATIVE-B question 21: the four option graphs were missing: the question asks which graph shows direct proportion, so each option now carries its own figure
--   MYP5-SUMMATIVE-B question 17: a stray $ set a whole clause as an equation, and a second one printed as a currency symbol in part (b)
--   MYP5-SUMMATIVE-B question 19: a stray $ printed as a currency symbol in the stem

begin;
set local lock_timeout = '5s';
set local statement_timeout = '90s';

-- MYP2-SUMMATIVE-B: the paper must exist, belong to this tenant, and be unattempted.
do $$
declare
  v_attempts integer;
begin
  perform 1 from public.exams
   where id = 'c0700000-0000-4000-8000-000000000002'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP2-SUMMATIVE-B: the fixed examination row is missing or belongs to another tenant';
  end if;
  perform 1 from public.quizzes
   where id = 'c0700000-0000-4000-8000-000000000001'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP2-SUMMATIVE-B: the fixed quiz row is missing or belongs to another tenant';
  end if;
  select count(*) into v_attempts from public.exam_attempts
   where exam_id = 'c0700000-0000-4000-8000-000000000002'::uuid;
  if v_attempts <> 0 then
    raise exception 'MYP2-SUMMATIVE-B: refusing to rewrite a paper with % attempt(s)', v_attempts;
  end if;
end $$;

-- MYP5-SUMMATIVE-B: the paper must exist, belong to this tenant, and be unattempted.
do $$
declare
  v_attempts integer;
begin
  perform 1 from public.exams
   where id = 'c0a00000-0000-4000-8000-000000000002'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP5-SUMMATIVE-B: the fixed examination row is missing or belongs to another tenant';
  end if;
  perform 1 from public.quizzes
   where id = 'c0a00000-0000-4000-8000-000000000001'::uuid and organization_id = '0a400000-0000-4000-8000-000000000001'::uuid
   for update;
  if not found then
    raise exception 'MYP5-SUMMATIVE-B: the fixed quiz row is missing or belongs to another tenant';
  end if;
  select count(*) into v_attempts from public.exam_attempts
   where exam_id = 'c0a00000-0000-4000-8000-000000000002'::uuid;
  if v_attempts <> 0 then
    raise exception 'MYP5-SUMMATIVE-B: refusing to rewrite a paper with % attempt(s)', v_attempts;
  end if;
end $$;

-- The repaired question content itself.
create temporary table _summative_b_repair (
  question_id uuid primary key,
  prompt text not null,
  prompt_doc jsonb not null,
  explanation text not null,
  option_count integer not null
) on commit drop;

insert into _summative_b_repair (question_id, prompt, prompt_doc, explanation, option_count)
select (x->>'q')::uuid, x->>'p', x->'d', x->>'e', (x->>'o')::integer
  from jsonb_array_elements('[{"q":"c0700000-0000-4000-8000-000000001021","p":"Which graph shows that $y$ is directly proportional to $x$?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which graph shows that "},{"type":"mathInline","attrs":{"latex":"y"}},{"type":"text","text":" is directly proportional to "},{"type":"mathInline","attrs":{"latex":"x"}},{"type":"text","text":"?"}]}]},"e":"Direct proportion always gives a straight-line graph passing through the origin (0, 0). Option B is a straight line that misses the origin, C is a curve and D is constant.","o":4},{"q":"c0a00000-0000-4000-8000-000000001017","p":"A tapered wall has 35 bricks in Row 1, decreasing by 3 bricks per row up to 11 bricks in Row 9. Find the total bricks in all 9 rows.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A tapered wall has 35 bricks in Row 1, decreasing by 3 bricks per row up to 11 bricks in Row 9. Find the total bricks in all 9 rows."}]}]},"e":"$S_9 = \\frac{9}{2}(35 + 11) = \\frac{9}{2} \\times 46 = 207$ bricks.","o":4},{"q":"c0a00000-0000-4000-8000-000000001019","p":"A solar array generates 18 kWh on Day 1 and increases by 2.5 kWh each day. On which day does daily output equal 53 kWh?","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A solar array generates 18 kWh on Day 1 and increases by 2.5 kWh each day. On which day does daily output equal 53 kWh?"}]}]},"e":"$18 + 2.5(n - 1) = 53 \\Rightarrow 2.5(n - 1) = 35 \\Rightarrow n - 1 = 14 \\Rightarrow n = 15$.","o":4}]'::jsonb) as x;

do $$
declare
  v_found integer;
  v_options integer;
  v_expected integer;
begin
  select count(*) into v_found
    from _summative_b_repair r
    join public.questions q on q.id = r.question_id
     and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid;
  if v_found <> 3 then
    raise exception 'summative B repair: found % of the expected 3 question rows', v_found;
  end if;

  -- Every option row that exists must be one the paper still authors, so an
  -- update can rewrite it in place instead of deleting anything.
  for v_expected, v_options in
    select r.option_count, count(o.id)
      from _summative_b_repair r
      left join public.question_options o on o.question_id = r.question_id
     group by r.question_id, r.option_count
  loop
    if v_expected <> v_options then
      raise exception 'summative B repair: a question authors % option(s) but the database has %; refusing to remap them', v_expected, v_options;
    end if;
  end loop;
end $$;

update public.questions q
   set prompt = r.prompt,
       prompt_doc = r.prompt_doc,
       explanation = r.explanation
  from _summative_b_repair r
 where q.id = r.question_id
   and q.organization_id = '0a400000-0000-4000-8000-000000000001'::uuid;

-- The printed options, including any figure an option carries.
update public.question_options o
   set content_doc = v.doc
  from (
    select (x->>'q')::uuid as question_id, (x->>'p')::integer as position, x->'d' as doc
      from jsonb_array_elements('[{"q":"c0700000-0000-4000-8000-000000001021","p":0,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A straight line through the origin"}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"domain":{"xMin":0,"xMax":6,"yMin":0,"yMax":12,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":false,"showLegend":false,"showIntersections":false,"equalScale":false},"functions":[{"id":"f","expression":"2x","color":"#0a5c36","style":"solid","width":2,"label":"2x","from":0,"to":6,"visible":true}],"points":[],"segments":[],"annotations":[],"strokes":[],"regions":[],"xLabel":"x","yLabel":"y","title":"Option A"}}}]}},{"q":"c0700000-0000-4000-8000-000000001021","p":1,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A straight line that does not pass through the origin"}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"domain":{"xMin":0,"xMax":6,"yMin":0,"yMax":12,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":false,"showLegend":false,"showIntersections":false,"equalScale":false},"functions":[{"id":"f","expression":"2x + 3","color":"#0a5c36","style":"solid","width":2,"label":"2x + 3","from":0,"to":6,"visible":true}],"points":[],"segments":[],"annotations":[],"strokes":[],"regions":[],"xLabel":"x","yLabel":"y","title":"Option B"}}}]}},{"q":"c0700000-0000-4000-8000-000000001021","p":2,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A curve through the origin"}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"domain":{"xMin":0,"xMax":6,"yMin":0,"yMax":12,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":false,"showLegend":false,"showIntersections":false,"equalScale":false},"functions":[{"id":"f","expression":"x^2/3","color":"#0a5c36","style":"solid","width":2,"label":"x^2/3","from":0,"to":6,"visible":true}],"points":[],"segments":[],"annotations":[],"strokes":[],"regions":[],"xLabel":"x","yLabel":"y","title":"Option C"}}}]}},{"q":"c0700000-0000-4000-8000-000000001021","p":3,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A horizontal straight line"}]},{"type":"graphBlock","attrs":{"spec":{"version":1,"domain":{"xMin":0,"xMax":6,"yMin":0,"yMax":12,"gridStep":null,"showGrid":true,"showAxes":true,"showCoordinates":false,"showLegend":false,"showIntersections":false,"equalScale":false},"functions":[{"id":"f","expression":"4","color":"#0a5c36","style":"solid","width":2,"label":"4","from":0,"to":6,"visible":true}],"points":[],"segments":[],"annotations":[],"strokes":[],"regions":[],"xLabel":"x","yLabel":"y","title":"Option D"}}}]}},{"q":"c0a00000-0000-4000-8000-000000001017","p":0,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"184"}]}]}},{"q":"c0a00000-0000-4000-8000-000000001017","p":1,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"198"}]}]}},{"q":"c0a00000-0000-4000-8000-000000001017","p":2,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"216"}]}]}},{"q":"c0a00000-0000-4000-8000-000000001017","p":3,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"207"}]}]}},{"q":"c0a00000-0000-4000-8000-000000001019","p":0,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Day 14"}]}]}},{"q":"c0a00000-0000-4000-8000-000000001019","p":1,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Day 15"}]}]}},{"q":"c0a00000-0000-4000-8000-000000001019","p":2,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Day 16"}]}]}},{"q":"c0a00000-0000-4000-8000-000000001019","p":3,"d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Day 21"}]}]}}]'::jsonb) as x
  ) as v
 where o.question_id = v.question_id and o.position = v.position;

-- Nothing is deleted and no UUID is reassigned, so a replay changes nothing.
commit;
